EPOCH_YEAR = 2000
EPOCH_WEEKDAY = 5
FIRST_VALID_YEAR = 2001
LAST_VALID_YEAR = 2099
MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
BUSINESS_DAY_RULES = ("FOLLOWING", "MODIFIED_FOLLOWING", "PRECEDING", "UNADJUSTED")


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def year_length(year):
    return 366 if is_leap(year) else 365


def month_length(year, month):
    if month == 2 and is_leap(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def split_date(text):
    return int(text[0:4]), int(text[5:7]), int(text[8:10])


def is_valid_date(text):
    year, month, day = split_date(text)
    if not FIRST_VALID_YEAR <= year <= LAST_VALID_YEAR or not 1 <= month <= 12:
        return False
    return 1 <= day <= month_length(year, month)


def day_number(year, month, day):
    number = day - 1
    for earlier_year in range(EPOCH_YEAR, year):
        number += year_length(earlier_year)
    for earlier_month in range(1, month):
        number += month_length(year, earlier_month)
    return number


def parse_date(text):
    year, month, day = split_date(text)
    return day_number(year, month, day)


def civil_date(number):
    year = EPOCH_YEAR
    while number >= year_length(year):
        number -= year_length(year)
        year += 1
    month = 1
    while number >= month_length(year, month):
        number -= month_length(year, month)
        month += 1
    return year, month, number + 1


def format_date(number):
    year, month, day = civil_date(number)
    return f"{year:04d}-{month:02d}-{day:02d}"


def weekday(number):
    return (number + EPOCH_WEEKDAY) % 7


class Calendar:
    def __init__(self, holidays):
        self.holidays = set(holidays)

    def is_business_day(self, number):
        return weekday(number) < 5 and number not in self.holidays

    def following(self, number):
        while not self.is_business_day(number):
            number += 1
        return number

    def preceding(self, number):
        while not self.is_business_day(number):
            number -= 1
        return number

    def adjust(self, number, rule):
        if rule == "FOLLOWING":
            return self.following(number)
        if rule == "PRECEDING":
            return self.preceding(number)
        if rule == "MODIFIED_FOLLOWING":
            following = self.following(number)
            if civil_date(following)[1] != civil_date(number)[1]:
                return self.preceding(number)
            return following
        return number

    def business_days_after(self, number, count):
        while count > 0:
            number += 1
            if self.is_business_day(number):
                count -= 1
        return number

DAY_COUNTS = ("30/360", "30E/360", "ACT/360", "ACT/365F", "ACT/ACT")
def is_end_of_february(year, month, day):
    return month == 2 and day == month_length(year, month)


def thirty_days(start_year, start_month, start_day, end_year, end_month, end_day):
    return 360 * (end_year - start_year) + 30 * (end_month - start_month) + (end_day - start_day)


def thirty_360(start, end):
    start_year, start_month, start_day = civil_date(start)
    end_year, end_month, end_day = civil_date(end)
    start_february = is_end_of_february(start_year, start_month, start_day)
    if start_february and is_end_of_february(end_year, end_month, end_day):
        end_day = 30
    if start_february:
        start_day = 30
    if end_day == 31 and start_day >= 30:
        end_day = 30
    if start_day == 31:
        start_day = 30
    return thirty_days(start_year, start_month, start_day, end_year, end_month, end_day)
def year_fraction(convention, start, end):
    if convention == "30/360":
        return thirty_360(start, end), 360
BISECTION_STEPS = 80
BASIS_POINT = 0.0001
LOWEST_YIELD = 0.0
HIGHEST_YIELD = 1.0


def bisection(function, low, high, target):
    for _ in range(BISECTION_STEPS):
        middle = (low + high) / 2
        if function(middle) > target:
            low = middle
        else:
            high = middle
    return (low + high) / 2


class RiskMeasures:
    def __init__(self, macaulay, modified, convexity, dv01):
        self.macaulay = macaulay
        self.modified = modified
        self.convexity = convexity
        self.dv01 = dv01


class YieldPricer:
    def __init__(self, flows, fraction, frequency, outstanding):
        self.flows = flows
        self.fraction = fraction
        self.frequency = frequency
        self.outstanding = outstanding

    def present_values(self, rate):
        first = 1 + self.fraction * rate / self.frequency
        growth = 1 + rate / self.frequency
        factor = 1.0
        values = []
        for cash_flow in self.flows:
            values.append(cash_flow / (first * factor))
            factor *= growth
        return values

    def dirty(self, rate):
        total = 0.0
        for value in self.present_values(rate):
            total += value
        return total * 100 / self.outstanding

    def solve(self, target):
        return bisection(self.dirty, LOWEST_YIELD, HIGHEST_YIELD, target)

    def in_range(self, target):
        return self.dirty(LOWEST_YIELD) > target > self.dirty(HIGHEST_YIELD)

    def risk(self, rate):
        growth = 1 + rate / self.frequency
        total = 0.0
        weighted = 0.0
        curvature = 0.0
        for index, value in enumerate(self.present_values(rate)):
            years = (index + self.fraction) / self.frequency
            total += value
            weighted += years * value
            curvature += years * (years + 1 / self.frequency) * value
        macaulay = weighted / total
        convexity = curvature / (total * growth * growth)
        dv01 = (self.dirty(rate - BASIS_POINT) - self.dirty(rate + BASIS_POINT)) / 2
        return RiskMeasures(macaulay, macaulay / growth, convexity, dv01)
def months_before(year, month, day, months, end_of_month):
    index = year * 12 + month - 1 - months
    year = index // 12
    month = index % 12 + 1
    if end_of_month:
        return day_number(year, month, month_length(year, month))
    return day_number(year, month, min(day, month_length(year, month)))


def coupon_schedule(issue, maturity, frequency, end_of_month, long_stub):
    year, month, day = civil_date(maturity)
    end_of_month_rule = end_of_month and day == month_length(year, month)
    step = 12 // frequency
    dates = []
    boundary = maturity
    while boundary > issue:
        dates.append(boundary)
        boundary = months_before(year, month, day, step * len(dates), end_of_month_rule)
    if long_stub and boundary != issue and len(dates) >= 2:
        dates.pop()
    dates.append(issue)
    dates.reverse()
    return dates
DAYS_PER_YEAR = 365
PAR_DAY_COUNT = "30/360"
LOWEST_RATE = 0.0
HIGHEST_RATE = 1.0
PAR_PRICE = 1.0
LOWEST_SPREAD = -0.5
HIGHEST_SPREAD = 0.5
    def __init__(self, days, rates):
        self.days = days
        self.rates = rates
    def zero_rate(self, day):
        if day <= self.days[0]:
            return self.rates[0]
        if day >= self.days[-1]:
            return self.rates[-1]
        index = 1
        while self.days[index] < day:
            index += 1
        if self.days[index] == day:
            return self.rates[index]
        low_day = self.days[index - 1]
        low_rate = self.rates[index - 1]
        weight = (day - low_day) / (self.days[index] - low_day)
        return low_rate + (self.rates[index] - low_rate) * weight
    def discount(self, day, spread):
        rate = self.zero_rate(day) + spread
        years, remainder = divmod(day, DAYS_PER_YEAR)
        growth = 1.0
        for _ in range(years):
            growth *= 1 + rate
        return 1 / (growth * (1 + rate * remainder / DAYS_PER_YEAR))
    def present_value(self, flows, spread):
        total = 0.0
        for day, cash_flow in flows:
            total += cash_flow * self.discount(day, spread)
        return total
def par_bond_flows(settlement, maturity, coupon, frequency):
    dates = coupon_schedule(settlement, maturity, frequency, False, False)
    flows = []
    for index in range(1, len(dates)):
        numerator, denominator = year_fraction(PAR_DAY_COUNT, dates[index - 1], dates[index])
        cash_flow = coupon * numerator / (10000 * denominator)
        if index == len(dates) - 1:
            cash_flow += 1
        flows.append((dates[index] - settlement, cash_flow))
    return flows
def bootstrap(settlement, pillars):
    days = []
    rates = []
    for maturity, coupon, frequency in pillars:
        flows = par_bond_flows(settlement, maturity, coupon, frequency)
        days.append(maturity - settlement)
        rate = bisection(
            lambda trial: ZeroCurve(days, rates + [trial]).present_value(flows, 0.0),
            LOWEST_RATE, HIGHEST_RATE, PAR_PRICE,
        )
        rates.append(rate)
    return ZeroCurve(days, rates)
def z_spread(curve, flows, target):
    return bisection(
        lambda spread: curve.present_value(flows, spread), LOWEST_SPREAD, HIGHEST_SPREAD, target
    )
INPUT_DIR = "input"
OUTPUT_DIR = "output"
BOND_TYPES = ("FIXED", "ZERO", "AMORT", "FRN")
FREQUENCIES = (1, 2, 4, 12)
OPTION_KEYS = {
    "FIXED": ("EOM", "LONG", "CALL"),
    "ZERO": ("EOM", "LONG"),
    "AMORT": ("EOM", "LONG", "SINK"),
    "FRN": ("EOM", "LONG", "LAG", "CAP", "FLOOR"),
}
REPEATABLE_KEYS = ("SINK", "CALL")
MAX_RATE = 1200
MIN_LAG = 1
MAX_LAG = 5
FACE_STEP = 100000
MAX_FACE = 10000000
MIN_CALL_PRICE = 100000
MAX_CALL_PRICE = 110000
BUCKET_NAMES = ("0-1Y", "1-3Y", "3-5Y", "5-10Y", "10Y+")
BUCKET_LIMITS = (365, 1095, 1825, 3650)
LOSER_COUNT = 3
CASHFLOWS_HEADER = "bond,period,start,end,payment,fraction,rate_bp,outstanding,coupon,principal"
ANALYTICS_HEADER = (
    "bond,clean,accrued,dirty,ytm,ytw,workout,next_payment,wal,"
